// Pega o ID que veio no payload do NocoDB
const id = $input.first().json.body.data.rows[0].Id;
const email_solicitante = $input.first().json.body.data.rows[0].email_solicitante;
const setor_responsavel = $input.first().json.body.data.rows[0].setor_responsavel;
const categoria = $input.first().json.body.data.rows[0].Categoria;
const status = $input.first().json.body.data.rows[0].Status;
const descricao = $input.first().json.body.data.rows[0]["Descrição"];
const atestado = $input.first().json.body.data.rows[0].Atestado

// Lista de caracteres permitidos para a parte aleatória (letras e números)
const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789@*';
let randomStr = '';

// Gera 10 caracteres aleatórios
for (let i = 0; i < 10; i++) {
  randomStr += chars.charAt(Math.floor(Math.random() * chars.length));
}

// Monta o código final 
const cod_chamado = `CHA-${randomStr}${id}`;

// Retorna as variáveis prontas para o nó do NocoDB
return {
  Id: id,
  cod_chamado: cod_chamado,
  email_solicitante: email_solicitante,
  setor_responsavel: setor_responsavel,
  categoria: categoria,
  status: status,
  descricao: descricao,
  atestado: atestado

};
